// WITHOUT injection - the service builds its own collaborator.

@Service
public class OrderService {

    private final PaymentGateway gateway = new StripeGateway();   // hard-wired

    public Receipt checkout(Order order) {
        return gateway.charge(order.total());
    }
}

// Now try to write a test for checkout().
//
//   new OrderService().checkout(order);
//
// It calls the real Stripe. Over the network. With a real card.
// There is no seam - no way to get a different gateway in there without
// editing OrderService itself.
//
// The same wall appears in production: supporting a second payment
// provider means changing this class, and changing a class that already
// works is how working code stops working.

// WITH injection - the collaborator is handed in.

@Service
public class OrderService {

    private final PaymentGateway gateway;      // an interface, not a class

    public OrderService(PaymentGateway gateway) {
        this.gateway = gateway;
    }

    public Receipt checkout(Order order) {
        return gateway.charge(order.total());
    }
}

// In production Spring supplies the real one.
// In a test you supply whatever you like:
//
//   PaymentGateway fake = order -> new Receipt("TEST-1", order);
//   Receipt r = new OrderService(fake).checkout(order);
//
// OUTPUT:
// Receipt[id=TEST-1] - no network, no card, runs in milliseconds.
//
// OrderService did not change between the two. That is the point:
// the class stopped deciding, so the decision can be made elsewhere.

// 1. CONSTRUCTOR INJECTION  (topic 5) - the recommended default
@Service
public class OrderService {

    private final PaymentGateway gateway;    // can be final

    public OrderService(PaymentGateway gateway) {
        this.gateway = gateway;
    }
}
// Since Spring 4.3, @Autowired is not needed when there is only
// one constructor. The object is never half-built.


// 2. SETTER INJECTION  (topic 6) - for genuinely optional dependencies
@Service
public class OrderService {

    private PaymentGateway gateway;          // cannot be final

    @Autowired
    public void setGateway(PaymentGateway gateway) {
        this.gateway = gateway;
    }
}
// The object exists before the setter runs, so there is a window
// in which the field is still null.


// 3. FIELD INJECTION  (topic 7) - shortest, and the one to avoid
@Service
public class OrderService {

    @Autowired
    private PaymentGateway gateway;          // no constructor, no setter
}
// Spring sets this by reflection. Convenient - and it is the form
// that cannot be constructed in a plain unit test.

// The practical difference, in one test.

// Constructor injection - the test just calls the constructor:
OrderService s = new OrderService(fakeGateway);          // compiles, works

// Field injection - there is nothing to call:
OrderService s = new OrderService();                      // gateway is null
s.checkout(order);
// OUTPUT:
// Exception in thread "main" java.lang.NullPointerException:
//   Cannot invoke "PaymentGateway.charge(...)" because "this.gateway" is null
//
// To test it you must either start a Spring context or use reflection
// (ReflectionTestUtils.setField) - both far heavier than a constructor call.

@Service
public class OrderService {

    private final PaymentGateway gateway;
    private final OrderRepository repository;

    public OrderService(PaymentGateway gateway, OrderRepository repository) {
        this.gateway = gateway;
        this.repository = repository;
    }

    public Receipt checkout(Order order) {
        Receipt receipt = gateway.charge(order.total());
        repository.save(order);
        return receipt;
    }
}

// Note what is NOT here: no @Autowired.
// Since Spring 4.3, a class with exactly one constructor is autowired
// through it automatically. Adding @Autowired is legal but redundant,
// and most modern codebases leave it off.

// The same class in a test - no Spring, no context, no annotations.

@Test
void chargesAndSaves() {
    FakeGateway gateway = new FakeGateway();
    FakeRepository repository = new FakeRepository();

    OrderService service = new OrderService(gateway, repository);
    Receipt receipt = service.checkout(new Order("A-1", 500));

    assertEquals(500, gateway.lastAmount);
    assertTrue(repository.contains("A-1"));
}

// OUTPUT:
// Test passed in 3 ms.
//
// The compiler enforces the setup: forget a dependency and the test
// does not compile. It cannot fail at runtime with a null field.

// BROKEN - two constructors, neither marked.
@Service
public class ReportService {

    private final Clock clock;
    private final ReportRepository repository;

    public ReportService(ReportRepository repository) {
        this(repository, Clock.systemUTC());
    }

    public ReportService(ReportRepository repository, Clock clock) {
        this.repository = repository;
        this.clock = clock;
    }
}

// OUTPUT at startup:
// BeanInstantiationException: Failed to instantiate [ReportService]:
//   No default constructor found
//
// Spring falls back to looking for a no-arg constructor, finds none,
// and gives up. It will not pick one of the two for you.

// FIXED - one constructor is marked as the one Spring should call.
@Service
public class ReportService {

    private final Clock clock;
    private final ReportRepository repository;

    public ReportService(ReportRepository repository) {
        this(repository, Clock.systemUTC());
    }

    @Autowired                                  // <-- Spring uses this one
    public ReportService(ReportRepository repository, Clock clock) {
        this.repository = repository;
        this.clock = clock;
    }
}

// Rule of thumb: with one constructor, no annotation.
// With several, exactly one gets @Autowired - annotating two is an error:
//   "Invalid autowire-marked constructor: ... Found constructor with
//    'required' Autowired annotation already"

// Written out by hand.
@Service
public class OrderService {

    private final PaymentGateway gateway;
    private final OrderRepository repository;
    private final NotificationService notifications;

    public OrderService(PaymentGateway gateway,
                        OrderRepository repository,
                        NotificationService notifications) {
        this.gateway = gateway;
        this.repository = repository;
        this.notifications = notifications;
    }
}

// The same class with Lombok.
@Service
@RequiredArgsConstructor
public class OrderService {

    private final PaymentGateway gateway;
    private final OrderRepository repository;
    private final NotificationService notifications;
}

// @RequiredArgsConstructor generates a constructor taking every final
// field (and every @NonNull field) - exactly the code above, at compile
// time. The class file is identical, so Spring's single-constructor rule
// applies and no @Autowired is needed.
//
// Two cautions:
//
// 1. Parameter ORDER follows FIELD order. Reordering two fields of the
//    same type silently swaps what gets injected - and it still compiles.
//    Rare, but it has cost people an afternoon.
//
// 2. Use @RequiredArgsConstructor, never @AllArgsConstructor. The latter
//    includes non-final fields too, which pulls configuration values and
//    mutable state into the injection contract.
//
// If a dependency needs a @Qualifier, Lombok cannot express it - write
// that one constructor by hand.

@Service
public class OrderService {

    private PaymentGateway gateway;        // cannot be final

    @Autowired
    public void setGateway(PaymentGateway gateway) {
        this.gateway = gateway;
    }

    public Receipt checkout(Order order) {
        return gateway.charge(order.total());
    }
}

// Unlike the constructor, @Autowired here is NOT optional.
// Without it Spring never calls the setter, the field stays null,
// and the failure is an NPE on the first checkout - at runtime,
// in production, not at startup.

// What Spring actually does, in order:

//  1. OrderService service = new OrderService();   <-- gateway is null here
//  2. service.setGateway(stripeGateway);           <-- now it is set
//  3. @PostConstruct methods run
//  4. the bean is handed out

// Step 1 is the window. Between the constructor returning and step 2,
// the object exists in an unusable state. Nothing in your code can
// observe that window in a simple case - but a constructor that tries
// to USE a dependency can:

@Service
public class OrderService {

    private PaymentGateway gateway;

    public OrderService() {
        gateway.warmUp();      // NullPointerException - the setter
    }                          // has not run yet and cannot have run

    @Autowired
    public void setGateway(PaymentGateway gateway) { this.gateway = gateway; }
}
// OUTPUT:
// BeanCreationException ... Caused by: java.lang.NullPointerException
//
// With constructor injection this class would not compile in the first
// place, which is the better outcome.

@Service
public class OrderService {

    @Autowired
    private PaymentGateway gateway;

    @Autowired
    private OrderRepository repository;

    public Receipt checkout(Order order) {
        Receipt receipt = gateway.charge(order.total());
        repository.save(order);
        return receipt;
    }
}

// Three lines instead of eight. This is why it spread, and it is the
// only argument in its favour.

// What Spring does, which is worth seeing plainly:

//  1. new OrderService()                     - both fields are null
//  2. AutowiredAnnotationBeanPostProcessor scans the class
//  3. for each @Autowired field:
//         Field f = OrderService.class.getDeclaredField("gateway");
//         f.setAccessible(true);             // bypasses 'private'
//         f.set(instance, stripeGateway);
//  4. the bean is handed out

// Step 3 is ordinary Java reflection with the access check switched off.
// Nothing magic is happening - which is exactly why anything else that
// wants to construct this object has to do the same thing.

// Try to unit test it.

@Test
void chargesAndSaves() {
    OrderService service = new OrderService();     // compiles fine
    service.checkout(new Order("A-1", 500));
}

// OUTPUT:
// java.lang.NullPointerException: Cannot invoke
//   "PaymentGateway.charge(int)" because "this.gateway" is null
//
// The constructor gave you nothing to pass. There is no setter. The
// fields are private. The object is unbuildable by design.

// The two ways out, both worse than the problem.

// (a) Reflection in the test - the test now knows the field NAME, so
//     renaming a private field breaks a test that never mentioned it.
@Test
void chargesAndSaves() {
    OrderService service = new OrderService();
    ReflectionTestUtils.setField(service, "gateway", fakeGateway);
    ReflectionTestUtils.setField(service, "repository", fakeRepository);
    ...
}

// (b) Start Spring - a unit test that needs a container.
@SpringBootTest
class OrderServiceTest {
    @Autowired OrderService service;
    @MockBean PaymentGateway gateway;
    ...
}
// Correct, but a context start is 2-10 seconds against 3 milliseconds
// for a constructor call. Multiply by a few hundred tests and the suite
// stops being run before every commit - which is the real cost.

// Idiomatic - nobody constructs a test class by hand.
@SpringBootTest
class OrderServiceIntegrationTest {

    @Autowired
    private OrderService service;          // fine

    @MockBean
    private PaymentGateway gateway;        // fine

    @Test
    void checkoutSavesTheOrder() { ... }
}

// @Value on a field - looks harmless, same trap.

@Service
public class OrderService {
    @Value("${shop.retry-limit}")
    private int retryLimit;                // untestable without reflection
}

// Constructor form - the value is just a parameter:
@Service
public class OrderService {
    private final int retryLimit;

    public OrderService(@Value("${shop.retry-limit}") int retryLimit) {
        this.retryLimit = retryLimit;
    }
}
// new OrderService(3) works in a test.

// Better still for a group of related settings - typed, validated,
// bound once, and injected like any other bean:

@ConfigurationProperties(prefix = "shop")
public record ShopProperties(int retryLimit, Duration timeout) { }

@Service
public class OrderService {
    private final ShopProperties props;
    public OrderService(ShopProperties props) { this.props = props; }
}

import org.springframework.stereotype.Component;
import org.springframework.context.annotation.*;
import jakarta.annotation.PostConstruct;
import jakarta.annotation.PreDestroy;

@Component
class LifecycleDemoBean {

    public LifecycleDemoBean() {
        System.out.println("1. Constructor called");
    }

    @PostConstruct
    public void init() {
        System.out.println("2. @PostConstruct - dependencies are injected now");
    }

    @PreDestroy
    public void destroy() {
        System.out.println("3. @PreDestroy - container shutting down");
    }
}

@Configuration
@ComponentScan
public class App {
    public static void main(String[] args) {
        AnnotationConfigApplicationContext ctx =
            new AnnotationConfigApplicationContext(App.class);
        ctx.close(); // triggers destroy phase
    }
}
// OUTPUT:
// 1. Constructor called
// 2. @PostConstruct - dependencies are injected now
// 3. @PreDestroy - container shutting down

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.context.annotation.*;
import org.springframework.stereotype.Component;

@Component
@Scope("singleton") // default, explicit here for clarity
class SingletonBean { }

@Component
@Scope("prototype")
class PrototypeBean { }

@Configuration
@ComponentScan
public class App {
    public static void main(String[] args) {
        AnnotationConfigApplicationContext ctx =
            new AnnotationConfigApplicationContext(App.class);

        SingletonBean s1 = ctx.getBean(SingletonBean.class);
        SingletonBean s2 = ctx.getBean(SingletonBean.class);
        System.out.println("Singleton same instance? " + (s1 == s2));

        PrototypeBean p1 = ctx.getBean(PrototypeBean.class);
        PrototypeBean p2 = ctx.getBean(PrototypeBean.class);
        System.out.println("Prototype same instance? " + (p1 == p2));
    }
}
// OUTPUT:
// Singleton same instance? true
// Prototype same instance? false

// GOOD: Constructor injection - easy to unit test without Spring at all
class Engine { void start() { System.out.println("Engine started"); } }

class Car {
    private final Engine engine; // immutable, guaranteed non-null

    public Car(Engine engine) {
        this.engine = engine;
    }

    void drive() {
        engine.start();
    }

    public static void main(String[] args) {
        // No Spring container required for this test!
        Car car = new Car(new Engine());
        car.drive();
    }
}
// OUTPUT:
// Engine started

// BAD: Field injection - cannot instantiate cleanly outside Spring
import org.springframework.beans.factory.annotation.Autowired;

class Car {
    @Autowired
    private Engine engine; // not final, not settable via constructor

    void drive() {
        engine.start(); // NullPointerException if "new Car()" used directly
                         // outside a Spring container - engine was never set!
    }
}
// OUTPUT (if tested with "new Car().drive()" without Spring):
// Exception in thread "main" java.lang.NullPointerException

import org.springframework.beans.factory.annotation.*;
import org.springframework.context.annotation.*;
import org.springframework.stereotype.Component;

interface Payment {
    void pay();
}

@Component("creditCard")
@Primary // default choice when ambiguous
class CreditCardPayment implements Payment {
    public void pay() { System.out.println("Paid using Credit Card"); }
}

@Component("upi")
class UpiPayment implements Payment {
    public void pay() { System.out.println("Paid using UPI"); }
}

@Component
class Checkout {
    private final Payment defaultPayment; // resolves via @Primary
    private final Payment upiPayment;     // resolves via @Qualifier

    public Checkout(Payment defaultPayment, @Qualifier("upi") Payment upiPayment) {
        this.defaultPayment = defaultPayment;
        this.upiPayment = upiPayment;
    }

    void run() {
        defaultPayment.pay();
        upiPayment.pay();
    }
}

@Configuration
@ComponentScan
public class App {
    public static void main(String[] args) {
        AnnotationConfigApplicationContext ctx =
            new AnnotationConfigApplicationContext(App.class);
        ctx.getBean(Checkout.class).run();
    }
}
// OUTPUT:
// Paid using Credit Card
// Paid using UPI

