//        +--> thread B: request-2's RequestContext
//
// Two cautions:
//
// 1. TARGET_CLASS uses CGLIB, so the class must not be final and needs
//    a no-arg constructor. INTERFACES is the JDK-proxy alternative when
//    the bean implements one.
//
// 2. Calling a method on that proxy outside a request - from a
//    @Scheduled job, an @Async thread, or a CommandLineRunner - throws
//    the same "Scope 'request' is not active" error, now at runtime
//    instead of startup. @Async is the usual culprit: the request
//    context does not follow the thread.

// Scope goes next to @Bean, and the proxy mode is set the same way.
@Configuration
public class AppConfig {

    @Bean
    @Scope(value = "prototype")
    public ReportBuilder reportBuilder() {
        return new ReportBuilder();
    }

    @Bean
    @RequestScope
    public RequestContext requestContext() {
        return new RequestContext();
    }
}

// Careful: proxyMode on a @Bean method proxies the RETURN TYPE.
// If the method returns an interface, use ScopedProxyMode.INTERFACES;
// TARGET_CLASS on an interface-typed @Bean method silently proxies the
// interface and can lose methods the implementation added.

// A custom scope - rarer, but the mechanism is small enough to know.
// Here: one instance per thread.

public class ThreadScope implements Scope {

    private final ThreadLocal<Map<String, Object>> beans =
        ThreadLocal.withInitial(HashMap::new);

    @Override
    public Object get(String name, ObjectFactory<?> factory) {
        return beans.get().computeIfAbsent(name, k -> factory.getObject());
    }

    @Override
    public Object remove(String name) { return beans.get().remove(name); }

    @Override public void registerDestructionCallback(String n, Runnable c) { }
    @Override public Object resolveContextualObject(String key) { return null; }
    @Override public String getConversationId() {
        return Thread.currentThread().getName();
    }
}

@Configuration
public class ScopeConfig implements BeanFactoryPostProcessor {
    @Override
    public void postProcessBeanFactory(ConfigurableListableBeanFactory bf) {
        bf.registerScope("thread", new ThreadScope());
    }
}

// Then: @Scope(value = "thread", proxyMode = ScopedProxyMode.TARGET_CLASS)
//
// Note the empty registerDestructionCallback: this implementation
// leaks, because a ThreadLocal on a pooled request thread is never
// cleared. Custom scopes are easy to write and easy to get wrong -
// which is the real reason they are rare.

package com.shop.service;

@Component
public class PricingEngine {

    private final TaxTable taxes;

    public PricingEngine(TaxTable taxes) {      // injected, because it is a bean
        this.taxes = taxes;
    }

    public Money price(Order order) { ... }
}

// Registered as bean "pricingEngine" - class name, first letter lowercased.
// Override it when the default reads badly:
//     @Component("pricing")

// Two conditions, both required:
//   1. the annotation is present
//   2. the class sits in a package that is scanned
//
// Miss either and the class is invisible. The failure is always the
// same message, at startup:
//
//   NoSuchBeanDefinitionException: No qualifying bean of type
//   'com.shop.service.PricingEngine' available

// Straight from the Spring source:

@Target(ElementType.TYPE)
@Retention(RetentionPolicy.RUNTIME)
@Documented
@Component                                   // <-- here
public @interface Service {
    @AliasFor(annotation = Component.class)
    String value() default "";
}

// Same for @Repository and @Controller. Component scanning does not
// look for four annotations - it looks for @Component, and finds these
// because they carry it.
//
// This is Spring's "meta-annotation" mechanism: an annotation that is
// itself annotated is treated as though it carried the inner one.

// So all four of these register a bean, identically:

@Component  public class PricingEngine  { }
@Service    public class OrderService   { }
@Repository public class OrderRepository{ }
@Controller public class OrderController{ }

// The differences are not in registration:
//
//   @Service     - no extra behaviour at all. Pure documentation.
//   @Repository  - adds exception translation: vendor SQLExceptions
//                  become Spring's DataAccessException hierarchy.
//   @Controller  - Spring MVC scans for these to find request handlers.
//                  A @Component with @GetMapping is NOT mapped.
//   @Component   - the generic case, when none of the three fit.
//
// @Repository and @Controller therefore DO something. @Service does
// not - but using it anyway keeps the layer readable at a glance, and
// tooling and architecture tests depend on the convention.

// 1. ON AN INTERFACE - ignored. Nothing to instantiate.
@Component
public interface PaymentGateway { }        // no bean is created


// 2. ON AN ABSTRACT CLASS - ignored, same reason.
@Component
public abstract class BaseService { }      // no bean


// 3. ON A CLASS YOU DO NOT OWN - impossible; you cannot edit the source.
//    Use a @Bean method instead:
@Bean
public ObjectMapper objectMapper() { return new ObjectMapper(); }


// 4. WITH NO USABLE CONSTRUCTOR - registered, then fails on creation.
@Component
public class ReportService {

    public ReportService(String templateName) { ... }   // String is not a bean
}

// OUTPUT:
// UnsatisfiedDependencyException: Error creating bean with name
// 'reportService': No qualifying bean of type 'java.lang.String'
//
// The class WAS found - scanning worked. It could not be built. Those
// are different failures with different fixes, and the message tells
// you which one you have:
//   "No qualifying bean of type <YourClass>"  -> not found (scanning)
//   "Error creating bean with name ..."       -> found, construction failed

@Service
public class OrderService {

    private final OrderRepository orders;
    private final InventoryService inventory;
    private final PaymentGateway payments;

    public OrderService(OrderRepository orders,
                        InventoryService inventory,
                        PaymentGateway payments) {
        this.orders = orders;
        this.inventory = inventory;
        this.payments = payments;
    }

    @Transactional
    public Order place(PlaceOrderCommand command) {

        // 1. rules the type system cannot express
        if (command.items().isEmpty()) {
            throw new EmptyOrderException();
        }
        if (!inventory.canFulfil(command.items())) {
            throw new OutOfStockException(command.items());
        }

        // 2. the decision
        Order order = Order.from(command);
        Money total = order.total();

        // 3. the effects, in one transaction
        inventory.reserve(order.items());
        Receipt receipt = payments.charge(total);
        order.markPaid(receipt);

        return orders.save(order);
    }
}

// The controller calling this has one line. The repository has none of
// these rules. Everything that makes this an ORDER system rather than
// a CRUD table is in this method.

// The anti-pattern - a "service" that is a forwarding layer.

@Service
public class OrderService {

    private final OrderRepository orders;

    public Order findById(Long id)  { return orders.findById(id).orElseThrow(); }
    public List<Order> findAll()    { return orders.findAll(); }
    public Order save(Order order)  { return orders.save(order); }
    public void delete(Long id)     { orders.deleteById(id); }
}

// Every method is one line and adds nothing. This is a real cost, not
// a style complaint: the layer must be read, tested and maintained,
// and it hides the repository without abstracting it.
//
// Two honest options:
//
//  1. If there genuinely are no rules yet, let the controller use the
//     repository directly and add the service when a rule appears.
//
//  2. If rules exist but live in the CONTROLLER, move them down. That
//     is usually what has happened.
//
// A pass-through service is not "good layering" - it is a layer with
// nothing in it.

// WRONG - @Transactional on the repository.
// Each call is its own transaction, so three separate commits.

@Repository
public class OrderRepository {
    @Transactional public Order save(Order o) { ... }        // commit 1
}

@Service
public class OrderService {
    public Order place(Command c) {
        inventory.reserve(...);       // commit 2
        Order o = orders.save(...);   // commit 1
        payments.record(...);         // commit 3
        return o;
    }
}
// If payments.record() throws, the stock is already reserved and the
// order is already saved. Nothing rolls back, because nothing was ever
// in the same transaction. The database now holds a paid-for order
// that was never paid for.


// RIGHT - one boundary, around the whole operation.
@Service
public class OrderService {

    @Transactional
    public Order place(Command c) {
        inventory.reserve(...);
        Order o = orders.save(...);
        payments.record(...);
        return o;
    }                                 // one commit, or one rollback
}

// This is also why @Transactional does NOT belong on a controller:
// the transaction would stay open while the response is serialised
// and written to the socket, holding a database connection for the
// duration of a slow client.

// WITHOUT translation - the caller must know MySQL.

public void save(User user) throws SQLException {
    try {
        jdbc.execute("INSERT INTO users ...");
    } catch (SQLException e) {
        if (e.getErrorCode() == 1062) {          // MySQL: duplicate entry
            throw new DuplicateUserException();
        }
        throw e;
    }
}

// Three problems:
//   * 1062 is a MySQL code. On PostgreSQL the same failure is SQLSTATE
//     23505 and errorCode 0. Moving database breaks this silently.
//   * SQLException is checked, so it spreads up through every caller
//     or gets wrapped by hand at every level.
//   * The service layer now contains database vendor knowledge.

// WITH @Repository - the same failure, already interpreted.

@Repository
public class UserRepository {

    private final JdbcTemplate jdbc;
    public UserRepository(JdbcTemplate jdbc) { this.jdbc = jdbc; }

    public void save(User user) {                    // no throws clause
        jdbc.update("INSERT INTO users (email) VALUES (?)", user.email());
    }
}

@Service
public class RegistrationService {

    public void register(String email) {
        try {
            users.save(new User(email));
        } catch (DuplicateKeyException e) {          // meaning, not a code
            throw new EmailAlreadyRegisteredException(email);
        }
    }
}

// DuplicateKeyException is raised whether the database is MySQL,
// PostgreSQL, Oracle or H2. The service reads as business logic
// because the vendor detail was translated one layer down.

// Retrying only what is worth retrying.

@Service
public class TransferService {

    @Retryable(retryFor = TransientDataAccessException.class,
               maxAttempts = 3,
               backoff = @Backoff(delay = 100, multiplier = 2))
    @Transactional
    public void transfer(Long from, Long to, Money amount) { ... }
}

// TransientDataAccessException is the parent of the deadlock and
// lock-timeout branches. Retrying those is correct - the transaction
// lost a race and the next attempt may win.
//
// Retrying DataIntegrityViolationException is not: a broken
// constraint will break again, three times, more slowly.

// No annotation needed. Spring Data finds this because
// @EnableJpaRepositories (implied by Spring Boot auto-configuration)
// scans for interfaces extending Repository.

public interface OrderRepository extends JpaRepository<Order, Long> {
    List<Order> findByCustomerId(Long customerId);
}

// Translation is already active - a constraint violation here arrives
// as DataIntegrityViolationException, not a raw PersistenceException.

// @Repository IS required when you write the class yourself:

@Repository                                    // <-- needed here
public class OrderReportRepository {

    private final EntityManager em;
    public OrderReportRepository(EntityManager em) { this.em = em; }

    public List<Row> monthlyTotals() {
        return em.createQuery("...", Row.class).getResultList();
    }
}

// Without the annotation this class is not even a bean. With it, both
// registration and translation apply.

// Summary:
//   interface extends JpaRepository   -> nothing needed
//   your own class using EntityManager
//     or JdbcTemplate                 -> @Repository

// This works.
@Controller
public class HomeController {

    @GetMapping("/home")
    public String home() { return "home"; }
}


// This does NOT. The class is a perfectly good bean - it is just
// never scanned for handlers.
@Component                                  // <-- wrong stereotype
public class HomeController {

    @GetMapping("/home")
    public String home() { return "home"; }
}

// OUTPUT:
// GET /home  ->  404 Not Found
//
// No error, no warning at startup. The mapping simply does not exist.
// When a URL 404s and the method is clearly right there, check the
// class annotation first - this is the most common cause.

// The Spring source - @RestController is a composed annotation:

@Target(ElementType.TYPE)
@Retention(RetentionPolicy.RUNTIME)
@Controller                                 // it IS a @Controller
@ResponseBody                               // ...with this added
public @interface RestController { }

// Which is why everything true of @Controller is true of it, and why
// @Controller + @ResponseBody on every method is exactly equivalent.

// SERVER-RENDERED - the String is a view name.
@Controller
public class OrderPageController {

    @GetMapping("/orders/{id}")
    public String view(@PathVariable Long id, Model model) {
        model.addAttribute("order", orders.require(id));
        return "orders/detail";              // -> templates/orders/detail.html
    }
}


// REST - the object becomes JSON.
@RestController
@RequestMapping("/api/orders")
public class OrderController {

    @GetMapping("/{id}")
    public OrderResponse get(@PathVariable Long id) {
        return OrderResponse.from(orders.require(id));
    }
}
// OUTPUT:
// HTTP/1.1 200 OK
// Content-Type: application/json
// {"id":1,"reference":"A-1","total":"49.99"}

@Controller                                // should be @RestController
@RequestMapping("/api")
public class StatusController {

    @GetMapping("/status")
    public String status() {
        return "OK";                       // meant as the body
    }
}

// OUTPUT:
// HTTP/1.1 500 Internal Server Error
//
// javax.servlet.ServletException: Circular view path [OK]: would
// dispatch back to the current handler URL again.
//
// Spring took "OK" as a VIEW NAME, found no view resolver that could
// render it, and fell back to forwarding to /OK - which mapped back
// here, hence "circular".

// Three ways to fix it, in order of preference:

@RestController                            // 1. the class is a REST class
public class StatusController { ... }

@Controller
public class StatusController {
    @GetMapping("/status")
    @ResponseBody                          // 2. this one method is a body
    public String status() { return "OK"; }
}

@Controller
public class StatusController {
    @GetMapping("/status")
    public ResponseEntity<String> status() {   // 3. ResponseEntity is
        return ResponseEntity.ok("OK");        //    always a body
    }
}

// The symptom to memorise: "Circular view path" almost always means
// a missing @ResponseBody, not a routing problem.

// Thin - and this is the target shape.
@RestController
@RequestMapping("/api/orders")
public class OrderController {

    private final OrderService orders;
    public OrderController(OrderService orders) { this.orders = orders; }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public OrderResponse place(@Valid @RequestBody PlaceOrderRequest request) {
        Order order = orders.place(request.toCommand());
        return OrderResponse.from(order);
    }
}

// Bind, validate, delegate, map. Four lines, no decisions.


// Fat - the same endpoint with the application inside it.
@RestController
public class OrderController {

    private final OrderRepository orders;          // repository in a controller
    private final InventoryRepository inventory;

    @PostMapping("/api/orders")
    @Transactional                                 // boundary in the wrong layer
    public Order place(@RequestBody PlaceOrderRequest request) {
        if (request.items().isEmpty()) {           // business rule
            throw new IllegalArgumentException();
        }
        if (!inventory.hasStock(request.items())) {   // business rule
            throw new IllegalStateException();
        }
        Order order = new Order(request);
        return orders.save(order);                 // entity leaked as response
    }
}

// Four separate problems, and the last is the quiet one: returning the
// entity ties the JSON contract to the database schema. Rename a column
// and every client breaks. It also serialises whatever the entity is
// lazily holding - see the Expert section.

// A stereotype for the outbound adapters in a hexagonal architecture.

@Target(ElementType.TYPE)
@Retention(RetentionPolicy.RUNTIME)
@Documented
@Component                                  // makes it a bean
public @interface Adapter {

    @AliasFor(annotation = Component.class)
    String value() default "";              // forwards the bean name
}

// Usage - registers a bean exactly like @Component:
@Adapter
public class StripeGateway implements PaymentGateway { }

// @AliasFor is what makes @Adapter("stripe") work. Without it the
// value() is a separate, ignored attribute and the bean keeps its
// default name.

// More useful: bundle the configuration that always goes together.

@Target(ElementType.TYPE)
@Retention(RetentionPolicy.RUNTIME)
@Component
@Transactional(readOnly = true)             // every query bean is read-only
@Validated                                  // method parameters are validated
public @interface QueryService { }

@QueryService
public class OrderQueryService {
    public List<Order> findRecent(@Min(1) int limit) { ... }
}

// One annotation instead of three, and impossible to apply
// inconsistently across the codebase.

// The payoff is enforcement. ArchUnit can now state the rule:
//
//   @ArchTest
//   static final ArchRule adaptersImplementPorts =
//       classes().that().areAnnotatedWith(Adapter.class)
//                .should().implement(resideInAPackage("..domain.port.."));
//
// A plain @Component cannot express that, because every bean has one.

// @Profile - registered only under the named profile.
@Component
@Profile("!prod")
public class SandboxGateway implements PaymentGateway { }

@Component
@Profile("prod")
public class StripeGateway implements PaymentGateway { }

// Exactly one exists at a time, so injection by type stays unambiguous.
// This is much safer than an if/else inside a single bean: the wrong
// implementation is not merely unused, it does not exist.


// @ConditionalOnProperty - registered based on configuration.
@Component
@ConditionalOnProperty(name = "shop.audit.enabled", havingValue = "true")
public class AuditListener { }

// Absent by default. matchIfMissing = true flips that to opt-out.


// @ConditionalOnMissingBean - "unless the application supplied one".
@Component
@ConditionalOnMissingBean(PaymentGateway.class)
public class NoOpGateway implements PaymentGateway { }

// ORDERING WARNING: on a scanned @Component this is fragile, because
// it evaluates in scan order - the "missing" answer depends on which
// class was read first. It is designed for auto-configuration, which
// Spring deliberately processes AFTER all user beans. Inside your own
// application, prefer @Profile or @ConditionalOnProperty, whose
// outcome does not depend on ordering.

// Cheaper measures that usually matter more than the index:

// 1. Scan a narrow root. @SpringBootApplication scans its own package
//    downwards, so putting the main class at the top of a broad
//    package tree scans everything under it.
@SpringBootApplication(scanBasePackages = "com.shop.orders")

// 2. Mark beans lazy so they are built on first use rather than at
//    startup. Global switch:
//        spring.main.lazy-initialization=true
//    Beware: it trades startup time for later failure. A misconfigured
//    bean now blows up on the first request instead of at startup,
//    which is usually the worse trade in production.

// 3. Measure before optimising. Startup timing per bean:
//        --debug        -> the auto-configuration report
//        ApplicationStartup / spring.startup actuator endpoint
//    Scanning is rarely the slow part; a DataSource connecting or a
//    Hibernate schema validation usually is.

// A port - the interface belongs to the domain, and the adapter
// implementing it lives outside. Here the interface earns its keep,
// because the direction of the dependency is the whole point.

package com.shop.domain.port;
public interface PaymentGateway {                  // domain owns this
    Receipt charge(Money amount);
}

package com.shop.adapter.stripe;
@Service
public class StripeGateway implements PaymentGateway { }   // adapter

// The domain compiles without knowing Stripe exists.


// A one-to-one interface that earns nothing:
public interface OrderService { Order place(Command c); }

@Service
public class OrderServiceImpl implements OrderService { }

// Two files, one behaviour, and every navigation lands on the
// interface first. If nothing else implements it and no boundary
// requires it, delete the interface.

// BUG 1: self-invocation. @Transactional on a method called from
//        within the same class does nothing.

@Service
public class OrderService {

    public void placeAll(List<Command> commands) {
        commands.forEach(this::place);      // 'this' is the RAW object
    }

    @Transactional
    public void place(Command c) { ... }    // NOT transactional here
}

// Called through placeAll(), each place() runs with no transaction at
// all. Called directly by a controller, it is transactional. Same
// method, different behaviour, no warning either way.
//
// Fix - put the boundary where the unit of work actually is:
@Service
public class OrderService {

    @Transactional                          // the whole batch is the unit
    public void placeAll(List<Command> commands) {
        commands.forEach(this::place);
    }

    void place(Command c) { ... }           // no annotation needed now
}

// If each item genuinely needs its OWN transaction, the loop and the
// item work must be on different beans - that is what makes the call
// cross a proxy boundary.

// BUG 2: a checked exception does not roll back.

@Service
public class OrderService {

    @Transactional
    public void place(Command c) throws PaymentFailedException {
        orders.save(order);
        throw new PaymentFailedException();   // checked
    }
}

// OUTPUT: the order is COMMITTED.
//
// @Transactional rolls back on RuntimeException and Error only. A
// checked exception propagates out and the transaction commits on the
// way - which is almost never what the author intended.
//
// Two fixes:
//   @Transactional(rollbackFor = Exception.class)
// or, better, make business failures unchecked:
//   public class PaymentFailedException extends RuntimeException { }
//
// Most modern Spring codebases use unchecked exceptions throughout for
// exactly this reason - Spring's own DataAccessException hierarchy is
// unchecked on the same principle.

// The cycle that appears naturally:
//   OrderService needs InvoiceService to raise an invoice
//   InvoiceService needs OrderService to look up the order
//
// Startup fails (Spring Boot 2.6+):
//   The dependencies of some of the beans in the application context
//   form a cycle

// FIX A - pass the data, do not fetch it.
//   The cheapest fix and usually the right one. InvoiceService needed
//   an Order, not an OrderService.
@Service
public class InvoiceService {
    public Invoice raise(Order order) { ... }    // no dependency at all
}

// FIX B - extract the shared work into a third bean.
//   A cycle nearly always means one responsibility living in two
//   classes; find it and give it its own name.
@Service
public class OrderPricing { Money total(Order o) { ... } }
// Both services depend on OrderPricing; neither depends on the other.

// FIX C - invert one direction with an event.
@Service
public class OrderService {
    private final ApplicationEventPublisher events;

    @Transactional
    public Order place(Command c) {
        Order order = orders.save(Order.from(c));
        events.publishEvent(new OrderPlaced(order));   // no compile-time edge
        return order;
    }
}

@Component
public class InvoiceListener {
    @TransactionalEventListener            // after commit, not before
    public void on(OrderPlaced event) { invoices.raise(event.order()); }
}

// @TransactionalEventListener over @EventListener matters here: the
// plain one fires inside the transaction, so an invoice is raised for
// an order that may still roll back.

// The non-Boot declaration, and what its absence looks like.

@Configuration
public class PersistenceConfig {

    @Bean
    public PersistenceExceptionTranslationPostProcessor exceptionTranslation() {
        return new PersistenceExceptionTranslationPostProcessor();
    }
}

// Without this bean, a @Repository is still a bean - it is just not
// proxied, so nothing is translated:
//
//   catch (DataIntegrityViolationException e)   // never fires
//
// and the raw exception surfaces instead:
//
//   jakarta.persistence.PersistenceException:
//     org.hibernate.exception.ConstraintViolationException
//
// Symptom to recognise: the catch block is right, the exception type
// is right, and it simply never matches.

// The boundary rule, made concrete.

@Repository
public class UserRepository {

    public void save(User user) {
        try {
            em.persist(user);
        } catch (DataIntegrityViolationException e) {   // NEVER matches
            throw new DuplicateUserException();
        }
    }
}

// Inside the method, em.persist() throws Hibernate's own exception.
// Translation happens in the proxy, on the way OUT - after this catch
// block has already declined to match.
//
// Correct: catch it in the SERVICE, one layer up, where the call has
// crossed the proxy.
//
// Or, if the repository must interpret it, catch the raw type:
//     catch (ConstraintViolationException e)   // org.hibernate
// which reintroduces exactly the vendor coupling translation exists
// to remove. Catching in the service is the better answer.

// A custom translator, for a vendor-specific condition Spring cannot
// know about - here Oracle's ORA-00060 (deadlock) exposed under a code
// a legacy driver reports differently.

@Component
public class OracleQuirkTranslator extends SQLErrorCodeSQLExceptionTranslator {

    @Override
    protected DataAccessException customTranslate(String task,
                                                  String sql,
                                                  SQLException ex) {
        if (ex.getErrorCode() == 60) {
            return new DeadlockLoserDataAccessException(task, ex);
        }
        if (ex.getErrorCode() == 54) {        // ORA-00054: resource busy
            return new CannotAcquireLockException(task, ex);
        }
        return null;                          // fall through to the default
    }
}

@Bean
public JdbcTemplate jdbcTemplate(DataSource ds, OracleQuirkTranslator t) {
    JdbcTemplate template = new JdbcTemplate(ds);
    template.setExceptionTranslator(t);
    return template;
}

// Returning null is the contract for "I have no opinion" - the default
// chain then runs. Returning an exception short-circuits it.
//
// Why bother: both of these are TransientDataAccessException subtypes,
// so classifying them correctly is what makes @Retryable retry the
// right failures and leave the rest alone.

// The repository states a fact.
public interface OrderRepository extends JpaRepository<Order, Long> {
    Optional<Order> findByReference(String reference);
}

// The service decides what the fact means. Different callers can
// decide differently:
@Service
public class OrderService {

    public Order require(String reference) {
        return orders.findByReference(reference)
                     .orElseThrow(() -> new OrderNotFoundException(reference));
    }

    public Order findOrCreate(String reference) {
        return orders.findByReference(reference)
                     .orElseGet(() -> orders.save(Order.draft(reference)));
    }
}

// Had the repository thrown on a missing row, findOrCreate() would
// have to catch an exception to implement its normal path - which is
// how exceptions end up used as control flow.

@Entity
public class Order {
    @Id private Long id;
    private String reference;
    private String internalNotes;                    // not for customers

    @OneToMany(fetch = FetchType.LAZY)
    private List<OrderLine> lines;

    @ManyToOne(fetch = FetchType.LAZY)
    private Customer customer;                       // -> and Customer has
}                                                    //    its own relations

@GetMapping("/api/orders/{id}")
public Order get(@PathVariable Long id) {            // returning the entity
    return orders.require(id);
}

// PROBLEM 1 - serialisation outside the transaction.
// The transaction closed in the service. Jackson now walks 'lines'
// and touches a lazy proxy with no session behind it:
//
//   HttpMessageNotWritableException:
//     Could not write JSON: could not initialize proxy - no Session
//
// Or, with open-session-in-view left on (Boot's default, and a bad
// one), it silently succeeds - by running one extra query per
// relation, per request, discovered later as an N+1 problem.

// PROBLEM 2 - the contract.
// internalNotes is now in the public API. So is every field anyone
// adds to the entity later. The JSON changes whenever the schema does,
// without anyone deciding that it should.

// The fix: a response record that states the contract explicitly.

public record OrderResponse(Long id, String reference, Money total,
                            List<LineResponse> lines) {

    public static OrderResponse from(Order order) {
        return new OrderResponse(
            order.getId(),
            order.getReference(),
            order.total(),
            order.getLines().stream().map(LineResponse::from).toList());
    }
}

@GetMapping("/api/orders/{id}")
public OrderResponse get(@PathVariable Long id) {
    return OrderResponse.from(orders.require(id));
}

// Three things this buys:
//   * the JSON is decided by the record, not by the schema
//   * internalNotes cannot leak, because it is not in the record
//   * from() runs inside the service call, while the session is open,
//     so lazy loading is a decision rather than an accident
//
// Also: turn off open-session-in-view, so the failure is loud rather
// than a silent N+1:
//     spring.jpa.open-in-view=false

