// Without @Primary this is the familiar startup failure:
//   NoUniqueBeanDefinitionException: expected single matching bean
//   but found 2: paypalGateway,stripeGateway
//
// With it, the ambiguity is resolved once, on the bean, rather than at
// every injection point.

// On a @Bean method it goes next to @Bean:

@Configuration
public class DataConfig {

    @Bean
    @Primary
    public DataSource primaryDataSource(ShopProperties p) { ... }

    @Bean
    public DataSource replicaDataSource(ShopProperties p) { ... }
}

// And the exceptions stay explicit about being exceptions:
@Repository
public class ReportRepository {
    public ReportRepository(@Qualifier("replicaDataSource") DataSource ds) { }
}

@Component @Primary public class StripeGateway implements PaymentGateway {}
@Component @Primary public class PaypalGateway implements PaymentGateway {}

// If NOTHING injects a bare PaymentGateway, the application starts.
// The moment something does:
//
// OUTPUT:
// NoUniqueBeanDefinitionException: No qualifying bean of type
// 'com.shop.PaymentGateway' available: more than one 'primary' bean
// found among candidates: [paypalGateway, stripeGateway]
//
// Read that message carefully - "more than one 'primary'" is a
// different problem from "found 2". The first means two beans claim
// to be the default; the second means none does.

// This bites most often when @Primary is added in two places by two
// people, or when a library bean is already @Primary and you add
// another without checking.

@Configuration
public class DataConfig {

    @Bean
    @Primary                                            // <-- required
    @ConfigurationProperties("app.datasource.primary")
    public DataSourceProperties primaryProperties() {
        return new DataSourceProperties();
    }

    @Bean
    @Primary                                            // <-- required
    public DataSource primaryDataSource(
            @Qualifier("primaryProperties") DataSourceProperties props) {
        return props.initializeDataSourceBuilder().build();
    }

    @Bean
    @ConfigurationProperties("app.datasource.replica")
    public DataSourceProperties replicaProperties() {
        return new DataSourceProperties();
    }

    @Bean
    public DataSource replicaDataSource(
            @Qualifier("replicaProperties") DataSourceProperties props) {
        return props.initializeDataSourceBuilder().build();
    }
}

// Why @Primary is not optional here: Spring Boot's own
// auto-configuration injects a bare DataSource to build the
// EntityManagerFactory, the JdbcTemplate and the transaction manager.
// Those are not your code, so you cannot add a @Qualifier to them.
//
// Without @Primary:
//   NoUniqueBeanDefinitionException while creating
//   'entityManagerFactory' - expected single matching bean but found
//   2: primaryDataSource,replicaDataSource
//
// The error names a bean you never wrote, which is what makes it
// confusing. @Primary is how you answer a question asked by code you
// do not control.

@Component class MoneyConverter  implements Converter<String, Money>   { }
@Component class InstantConverter implements Converter<String, Instant> { }

@Service
public class Pricing {
    // Unambiguous - two beans implement Converter, but only one
    // implements Converter<String, Money>.
    public Pricing(Converter<String, Money> converter) { }
}

// Works through the whole hierarchy:
public interface Repository<T> { }
@Component class OrderRepository    implements Repository<Order> { }
@Component class CustomerRepository implements Repository<Customer> { }

public Service(Repository<Order> orders) { }        // resolves correctly

// And with collections, the element type is respected:
public Service(List<Handler<OrderEvent>> handlers) { }
// -> only the handlers for OrderEvent, not every Handler.

// LIMIT: type erasure at the injection point still applies to raw
// declarations. Injecting a raw 'Converter converter' matches both and
// fails with NoUniqueBeanDefinitionException - the generics have to be
// written for Spring to use them.

@Component("stripeGateway") class StripeGateway implements PaymentGateway {}
@Component("paypalGateway") class PaypalGateway implements PaymentGateway {}

public class OrderService {

    @Autowired
    private PaymentGateway paypalGateway;
    // by TYPE first -> two candidates -> falls through to the name
    // match -> PaypalGateway. Works, but only via the fallback.

    @Resource
    private PaymentGateway paypalGateway;
    // by NAME first -> "paypalGateway" -> PaypalGateway, immediately.
    // No ambiguity was ever considered.

    @Resource(name = "stripeGateway")
    private PaymentGateway gateway;
    // explicit name - the @Resource equivalent of @Qualifier.
}

// The difference only shows when several beans match the type, which
// is precisely when a bug is expensive. Pick one convention per
// codebase.

// 1. INJECTING A CONFIGURATION VALUE, NOT A BEAN.
//    @Autowired resolves beans. A String, int or Duration from
//    application.properties is not a bean.

@Autowired
private String apiKey;                          // WRONG

// OUTPUT:
// NoSuchBeanDefinitionException: No qualifying bean of type
// 'java.lang.String' available
//
// (Or worse: if some @Bean method happens to return a String, that
//  unrelated value is injected instead.)

// Correct - @Value reads the Environment:
public OrderService(@Value("${payment.api-key}") String apiKey) { }

// Better for a group of settings - typed, validated, one bean:
@ConfigurationProperties(prefix = "payment")
public record PaymentProperties(String apiKey, Duration timeout) { }

// 2. AUTOWIRING INTO AN OBJECT SPRING DID NOT CREATE.

@Component
public class OrderProcessor {
    @Autowired private OrderRepository repository;
}

// somewhere else:
OrderProcessor p = new OrderProcessor();        // compiles fine
p.process(order);

// OUTPUT:
// NullPointerException: Cannot invoke "OrderRepository.save(...)"
// because "this.repository" is null
//
// @Autowired is not a language feature. It is an instruction to the
// container, and the container never saw this object. Nothing will
// ever populate that field.
//
// The fix is to inject OrderProcessor rather than construct it. If it
// genuinely must be created per call, it should take its dependencies
// as constructor arguments and not be a bean at all.

// Define the roles as annotations.

@Target({ ElementType.FIELD, ElementType.PARAMETER, ElementType.TYPE,
          ElementType.METHOD })
@Retention(RetentionPolicy.RUNTIME)
@Qualifier                                    // <-- makes it a qualifier
public @interface Card { }

@Target({ ElementType.FIELD, ElementType.PARAMETER, ElementType.TYPE,
          ElementType.METHOD })
@Retention(RetentionPolicy.RUNTIME)
@Qualifier
public @interface Wallet { }


// On the beans:
@Component @Card   public class StripeGateway implements PaymentGateway { }
@Component @Wallet public class PaypalGateway implements PaymentGateway { }


// At the injection point:
@Service
public class OrderService {
    public OrderService(@Card PaymentGateway gateway) { }
}

// What this buys over @Qualifier("card"):
//   * a typo is a compile error, not a startup error
//   * "find usages" on @Card works; on a string it does not
//   * renaming the role is a refactor, not a search-and-replace
//   * the IDE autocompletes the available roles

// Qualifiers with attributes, for a family of related choices.

@Target({ ElementType.FIELD, ElementType.PARAMETER, ElementType.TYPE,
          ElementType.METHOD })
@Retention(RetentionPolicy.RUNTIME)
@Qualifier
public @interface Gateway {
    Provider value();
    boolean sandbox() default false;
}

public enum Provider { STRIPE, PAYPAL, ADYEN }

@Component @Gateway(Provider.STRIPE)
public class StripeGateway implements PaymentGateway { }

@Component @Gateway(value = Provider.STRIPE, sandbox = true)
public class StripeSandboxGateway implements PaymentGateway { }

// EVERY attribute must match for the bean to be selected:
public OrderService(@Gateway(Provider.STRIPE) PaymentGateway g) { }
// -> StripeGateway. The sandbox one has sandbox=true, which does not
//    match the default false, so it is excluded.

public TestHarness(@Gateway(value = Provider.STRIPE, sandbox = true)
                   PaymentGateway g) { }
// -> StripeSandboxGateway.

@Component @Qualifier("preCheck")  class AmountValidator  implements Validator {}
@Component @Qualifier("preCheck")  class AddressValidator implements Validator {}
@Component @Qualifier("postCheck") class StockValidator   implements Validator {}
@Component @Qualifier("postCheck") class FraudValidator   implements Validator {}

@Service
public class OrderValidator {

    private final List<Validator> before;
    private final List<Validator> after;

    public OrderValidator(@Qualifier("preCheck")  List<Validator> before,
                          @Qualifier("postCheck") List<Validator> after) {
        this.before = before;
        this.after = after;
    }
}

// 'before' gets two validators, 'after' gets the other two. No
// registry, no manual filtering, no if-statements - the grouping is
// declared on the beans themselves.
//
// Adding a validator to a phase is one annotation on a new class.

// CAUTION: a qualified List that matches NOTHING fails at startup with
// NoSuchBeanDefinitionException, the same as any other empty
// collection injection. If a phase may legitimately be empty:
//     ObjectProvider<Validator> provider;   // then .stream()
// or mark the injection point not required.

// 1. A TYPO, OR A NAME THAT DOES NOT EXIST.

public OrderService(@Qualifier("stripGateway") PaymentGateway g) { }
//                               ^ missing 'e'

// OUTPUT:
// NoSuchBeanDefinitionException: No qualifying bean of type
// 'com.shop.PaymentGateway' available: expected at least 1 bean which
// qualifies as autowire candidate. Dependency annotations:
// {@org.springframework.beans.factory.annotation.Qualifier("stripGateway")}
//
// Note it says "at least 1" - the qualifier excluded BOTH candidates,
// so the message is about zero matches even though two beans exist.
// That wording sends people looking for a missing bean rather than a
// misspelt qualifier. Read the "Dependency annotations" line.


// 2. THE DECAPITALISATION RULE, when relying on the name fallback.

@Component public class JWTService { }         // bean name: "JWTService"

@Qualifier("jwtService")                       // FAILS
@Qualifier("JWTService")                       // correct

// Two leading capitals means the name is left alone. Another reason to
// declare an explicit qualifier rather than lean on the class name.

// 3. QUALIFYING A BEAN THAT DOES NOT EXIST YET AT THAT NAME.
//    @Bean method names are the fallback qualifier, so renaming the
//    METHOD renames the bean and breaks the qualifier silently at the
//    other end of the codebase.

@Bean
public DataSource replicaDataSource(...) { ... }     // renamed to readReplica()

public ReportRepository(@Qualifier("replicaDataSource") DataSource ds) { }
// -> now fails at startup, and the compiler said nothing.
//
// With @Qualifier("readOnly") declared on the @Bean method, the rename
// is invisible to callers.


// 4. EXPECTING @Qualifier TO PICK BETWEEN TWO @Primary BEANS.
//    It does, and that is fine - but two @Primary beans of one type is
//    an error in its own right the moment ANY unqualified injection
//    point exists:
//
//    NoUniqueBeanDefinitionException: more than one 'primary' bean
//    found among candidates: [stripeGateway, paypalGateway]
//
//    @Primary means "the default". There can only be one.

@Component @Primary @Order(2) class StripeGateway implements PaymentGateway {}
@Component          @Order(1) class PaypalGateway implements PaymentGateway {}

@Service
public class GatewayRouter {

    public GatewayRouter(PaymentGateway one,            // -> Stripe (primary)
                         List<PaymentGateway> all,      // -> BOTH
                         Map<String, PaymentGateway> byName) {

        // all  == [PaypalGateway, StripeGateway]   <- @Order, not @Primary
        // byName == { "stripeGateway": ..., "paypalGateway": ... }
    }
}

// This is the intended design, not a gap: a fallback strategy list and
// a default choice are different questions, so they use different
// annotations.

@Component @Priority(1) class DatabaseResolver  implements ConfigResolver {}
@Component @Priority(2) class FileResolver      implements ConfigResolver {}
@Component @Priority(3) class DefaultResolver   implements ConfigResolver {}

public ConfigService(ConfigResolver resolver) { }   // -> DatabaseResolver

// The ranking is documented once, on the beans, and stays meaningful
// if the top one is later removed - FileResolver takes over with no
// other edit. @Primary would have needed moving.
//
// Note @Priority does NOT work on a @Bean method:
//
//   @Bean @Priority(1) public ConfigResolver resolver() { ... }  // ignored
//
// It is read from the bean's CLASS. For @Bean-declared beans, use
// @Primary.

// USUALLY UNNECESSARY.
@Bean
@Primary
public ObjectMapper objectMapper() { ... }

// Boot's JacksonAutoConfiguration declares its ObjectMapper with
// @ConditionalOnMissingBean, and auto-configuration is processed AFTER
// all user configuration. So yours simply exists first and Boot's
// never registers. There is only one bean, and nothing to be primary
// over.
//
// Adding @Primary is harmless here but misleading - it implies a
// competing bean that is not there.


// WHEN IT IS GENUINELY NEEDED: the auto-configured bean is NOT
// conditional, so both exist.

@Bean
@Primary
public TaskExecutor customTaskExecutor() { ... }

// Some auto-configurations register unconditionally, or register a
// bean under a name you cannot predict. Then two beans of the type
// really do exist and @Primary decides.
//
// How to tell which situation you are in - ask the running context
// rather than guess:
//
//   context.getBeanNamesForType(ObjectMapper.class)
//   -> ["objectMapper"]                  one bean; @Primary is noise
//   -> ["objectMapper", "jacksonObjectMapper"]
//                                        two; @Primary is doing work
//
// or from the command line:
//   curl localhost:8080/actuator/beans | jq '...'

// The related trap: @Primary does not stop a bean from EXISTING.

@Bean @Primary
public DataSource appDataSource() { ... }

// If an auto-configured DataSource also exists, it is still there -
// still holding a connection pool, still opening connections, still
// participating in health checks. @Primary only means it is not
// injected by default.
//
// To actually remove it:
//     @SpringBootApplication(exclude = DataSourceAutoConfiguration.class)
//
// Symptom that you have this: connection counts or pool metrics twice
// what you expect, or a health endpoint reporting a database you
// thought you had replaced.

// WORKS - everything is under the main class's package.

com.shop
 |- ShopApplication.java          @SpringBootApplication  <- scan root
 |- order
 |   |- OrderController.java      @RestController   found
 |   |- OrderService.java         @Service          found
 |- payment
     |- StripeGateway.java        @Component        found


// BROKEN - a sibling package, not a child.

com
 |- shop
 |   |- ShopApplication.java      @SpringBootApplication  <- scan root
 |   |- order
 |       |- OrderService.java     @Service          found
 |- billing
     |- InvoiceService.java       @Service          NOT FOUND

// com.billing is not under com.shop, so it is never scanned.
//
// OUTPUT:
// UnsatisfiedDependencyException: Error creating bean with name
// 'orderService': ... No qualifying bean of type
// 'com.billing.InvoiceService' available
//
// The message names the class you wanted, which sends people looking
// for a missing annotation. The annotation is fine - the package is
// wrong.

// Three fixes, best first.

// 1. Move the main class up so everything is beneath it. This is why
//    the convention is to put it in the ROOT package.
com
 |- ShopApplication.java          <- scan root is now 'com'
 |- shop
 |- billing

// 2. Name the packages explicitly.
@SpringBootApplication(scanBasePackages = { "com.shop", "com.billing" })

// 3. Use classes instead of strings - refactor-safe, because moving
//    or renaming the package updates this automatically.
@SpringBootApplication
@ComponentScan(basePackageClasses = { ShopApplication.class,
                                      InvoiceService.class })

// Prefer (3) over (2): a string package name is not checked by
// anything, so a typo or a later package rename fails silently at
// runtime rather than at compile time.

// Confirming what was actually scanned, rather than reasoning about it.

@Component
public class ScanReport implements CommandLineRunner {

    private final ApplicationContext context;
    public ScanReport(ApplicationContext context) { this.context = context; }

    @Override
    public void run(String... args) {
        Arrays.stream(context.getBeanDefinitionNames())
              .filter(n -> !n.startsWith("org.springframework"))
              .sorted()
              .forEach(System.out::println);
    }
}

// Or, without writing code, turn on the scanner's own logging:
//
//   logging.level.org.springframework.context.annotation
//       .ClassPathBeanDefinitionScanner=DEBUG
//
// OUTPUT:
// Identified candidate component class:
//   file [.../com/shop/order/OrderService.class]
// Identified candidate component class:
//   file [.../com/shop/payment/StripeGateway.class]
//
// If your class is not in that list, it was never scanned - stop
// looking at the class and look at the packages.

@Configuration
@ComponentScan(
    basePackages = "com.shop",

    excludeFilters = @ComponentScan.Filter(
        type = FilterType.ASSIGNABLE_TYPE,
        classes = { LegacyOrderService.class, ExperimentalGateway.class }),

    includeFilters = @ComponentScan.Filter(
        type = FilterType.ANNOTATION,
        classes = Adapter.class)          // a custom stereotype of ours
)
public class AppConfig { }

// The five filter types:
//
//   ANNOTATION       classes carrying an annotation   (most common)
//   ASSIGNABLE_TYPE  classes of / implementing a type (most precise)
//   REGEX            class name matches a pattern
//   ASPECTJ          an AspectJ type pattern
//   CUSTOM           your own TypeFilter implementation

// CAUTION: excludeFilters do NOT apply to beans registered any other
// way. Excluding a class that is also declared by a @Bean method, an
// @Import, or an auto-configuration leaves it registered - the filter
// only controls what SCANNING picks up.

