// The key detail: dependencies stay as NESTED JAR FILES. Standard Java
// cannot load a jar inside a jar, which is why Boot ships its own
// classloader. Main-Class is the LAUNCHER, not your class - the
// launcher builds a classloader over BOOT-INF/lib and then calls
// Start-Class.
//
// Consequences:
//   * java -jar works anywhere with a JVM
//   * unzipping and running your class directly does NOT work
//   * java -cp order-service.jar com.dhipan...Application does NOT work
//     (the dependencies are invisible to the normal classloader)
//
// To run the exploded form, extract it properly:
//     java -Djarmode=tools -jar order-service.jar extract
//     java -cp 'order-service/lib/*:order-service/order-service.jar' \
//          com.dhipan.orderservice.OrderServiceApplication
//
// (Boot 3.3+ uses -Djarmode=tools; earlier versions used
//  -Djarmode=layertools with the 'extract' command.)

// The scanning consequence people hit next.
//
// The main class lives in api, so @SpringBootApplication scans
// com.dhipan.api and below. Beans in the 'common' or 'domain' modules
// are NOT scanned - different package trees, and jar boundaries do not
// matter, package names do.
//
// Two correct answers:

// (a) Share a root package across modules, so one scan covers them:
//     common  -> com.dhipan.order.common
//     domain  -> com.dhipan.order.domain
//     api     -> com.dhipan.order.api
//     main class in com.dhipan.order
//
// (b) Have each library expose an auto-configuration, which is the
//     right approach when the module is genuinely reusable:
//     common/src/main/resources/META-INF/spring/
//       org.springframework.boot.autoconfigure.AutoConfiguration.imports
//
// Do NOT use @ComponentScan("com.dhipan.common") in the application -
// it makes the library's internal package layout part of its public
// contract.

// dhipan-spring-boot-autoconfigure/src/main/java/...

@AutoConfiguration
@ConditionalOnClass(AuditWriter.class)             // only if the lib is present
@EnableConfigurationProperties(AuditProperties.class)
@ConditionalOnProperty(prefix = "dhipan.audit",
                       name = "enabled",
                       matchIfMissing = true)      // on by default, opt-out
public class AuditAutoConfiguration {

    @Bean
    @ConditionalOnMissingBean                      // the app can override
    public AuditWriter auditWriter(AuditProperties props, DataSource ds) {
        return new JdbcAuditWriter(ds, props.tableName());
    }

    @Bean
    @ConditionalOnMissingBean
    @ConditionalOnBean(AuditWriter.class)
    public AuditAspect auditAspect(AuditWriter writer) {
        return new AuditAspect(writer);
    }
}

@ConfigurationProperties(prefix = "dhipan.audit")
@Validated
public record AuditProperties(
        /** Table that audit rows are written to. */
        @NotBlank String tableName,
        /** Whether to record the full request body. */
        boolean includeBody) {

    public AuditProperties {
        if (tableName == null) tableName = "audit_log";
    }
}

// Every bean is @ConditionalOnMissingBean. That is the contract of a
// well-behaved starter: supply a default, and get out of the way the
// moment the application defines its own.

class AuditAutoConfigurationTest {

    private final ApplicationContextRunner runner = new ApplicationContextRunner()
        .withConfiguration(AutoConfigurations.of(AuditAutoConfiguration.class));

    @Test
    void registersDefaultWriter() {
        runner.withBean(DataSource.class, () -> mock(DataSource.class))
              .run(context -> {
                  assertThat(context).hasSingleBean(AuditWriter.class);
                  assertThat(context.getBean(AuditProperties.class).tableName())
                      .isEqualTo("audit_log");
              });
    }

    @Test
    void backsOffWhenApplicationDefinesItsOwn() {
        runner.withUserConfiguration(CustomWriterConfig.class)
              .run(context -> assertThat(context)
                  .getBean(AuditWriter.class)
                  .isInstanceOf(CustomAuditWriter.class));
    }

    @Test
    void disabledByProperty() {
        runner.withPropertyValues("dhipan.audit.enabled=false")
              .run(context -> assertThat(context)
                  .doesNotHaveBean(AuditWriter.class));
    }

    @Test
    void absentWhenLibraryMissing() {
        runner.withClassLoader(new FilteredClassLoader(AuditWriter.class))
              .run(context -> assertThat(context)
                  .doesNotHaveBean(AuditAutoConfiguration.class));
    }
}

