    private List<Premium> premiumList = new ArrayList<>();

    @OneToMany(mappedBy = "user")
    private List<Claim> claimList = new ArrayList<>();

    @OneToMany(mappedBy = "user")
    private List<PaymentMode> paymentModeList = new ArrayList<>();

    // getters and setters
